SELECT x.TASK_PARAMETER_ID AS row_id, x.ACTIVE_FLAG AS active_flag, 'Y' AS well_formed, x.TASK_ID AS task_id, p.PIPELINE_CODE AS pipeline_code, t.TASK_CODE AS task_code, x.PARAMETER_NAME AS parameter_name, x.PARAMETER_VALUE AS parameter_value FROM CFG_TASK_PARAMETERS x JOIN CFG_TASKS t ON t.TASK_ID = x.TASK_ID JOIN CFG_PIPELINES p ON p.PIPELINE_ID = t.PIPELINE_ID ORDER BY 1
